import{_ as t,o,c as a,a3 as s}from"./chunks/framework.d6OaePA7.js";const d=JSON.parse('{"title":"Centos分区合并","description":"","frontmatter":{},"headers":[],"relativePath":"pages/explore/others/Centos分区合并.md","filePath":"pages/explore/others/Centos分区合并.md","lastUpdated":1693917276000}'),i={name:"pages/explore/others/Centos分区合并.md"};function r(l,e,g,c,n,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="centos分区合并" tabindex="-1">Centos分区合并 <a class="header-anchor" href="#centos分区合并" aria-label="Permalink to &quot;Centos分区合并&quot;">​</a></h1><blockquote><p>本文根据UP主<a href="https://space.bilibili.com/253977174" target="_blank" rel="noreferrer">左左经验</a>视频整理而成</p></blockquote><p>在<code>物理机安装Linux同时...</code> 一节为了搭建自己的服务器, 所以我在自己的小主机上装了一个新的Centos系统. 装完系统后发现默认的硬盘分成了两个区, 一个是root, 一个是home. 这就导致root空间过小, 需要将home区合并到root区.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204212357967.png" alt="image-20221204212357967"></p><p>可以看到, 上面root分区是 50G, home分区是61G(这个硬盘是128G的垃圾固态).</p><ol><li><p>删除home分区 使用<code>nano /etc/fstab</code> 命令 <img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204213104007.png" alt="image-20221204213104007"></p></li><li><p>卸载home分区 <code>umount /home</code> 卸载后如下所示 <img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204213314364.png" alt="image-20221204213314364"></p></li><li><p>查看有哪些lv分区 <code>lvscan</code><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204213453675.png" alt="image-20221204213453675"></p></li><li><p>卸载home分区 <code>lvremove /dev/mapper/centos-home</code><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204213622124.png" alt="image-20221204213622124"></p></li><li><p>查看当前剩余空间 <code>vgdisplay</code><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204213816271.png" alt="image-20221204213816271"></p></li><li><p>将空闲的空间扩容到root <code>lvextend -l +100%free /dev/mapper/centos-root</code><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204214013919.png" alt="image-20221204214013919"> 此时空间还没有变大 <img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204214049819.png" alt="image-20221204214049819"></p></li><li><p>再执行命令刷新 <code>xfs_growfs /dev/mapper/centos-root</code> 此时可以看到容量更新成功了 <img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20221204214307953.png" alt="image-20221204214307953"></p></li></ol>',6)])])}const h=t(i,[["render",r]]);export{d as __pageData,h as default};
